SELECT n.id, n.publication_id, (n.published_at+ifnull(n.published_offset,0)*60)/86400 AS p, (n.dispatched_at+ifnull(n.dispatched_offset,0)*60)/86400 AS q, o.id AS oid, o.publication_id AS opub, o.fetch_id AS ofetch, (o.published_at+ifnull(o.published_offset,0)*60)/86400 AS op, (o.dispatched_at+ifnull(o.dispatched_offset,0)*60)/86400 AS oq FROM notices n CROSS JOIN notices o ON o.source = 'doe' AND o.publication_id >= substr(n.publication_id,1,36)||'-' AND o.publication_id < substr(n.publication_id,1,36)||'.' AND o.id <> n.id WHERE n.fetch_id = 439 AND +n.profile = 'eforms:eforms-sdk-0.1' AND n.dispatched_at IS NOT NULL AND (n.published_at+ifnull(n.published_offset,0)*60)/86400 < 19448 LIMIT 12
